from pathlib import Path
import json, html, shutil
R=Path.cwd(); O=R/'output/pdf'; O.mkdir(parents=True,exist_ok=True); A=O/'assets'; A.mkdir(exist_ok=True)
shots=R/'docs/screenshots/offline-v3'
for f in shots.glob('*.png'): shutil.copy2(f,A/f.name)
E=json.loads((R/'artifacts/evaluation.json').read_text(encoding='utf-8'))
css='''@page{size:Letter;margin:0}*{box-sizing:border-box}body{margin:0;background:#e7e9e6;color:#171b19;font-family:"Microsoft YaHei",Arial,sans-serif;font-size:15px;line-height:1.65}.page{width:816px;height:1056px;margin:18px auto;background:white;padding:44px 56px 48px;position:relative;break-after:page;overflow:hidden}.page:last-child{break-after:auto}.running{font-size:11px;letter-spacing:1px;color:#555;border-bottom:1px solid #d9d9d9;padding-bottom:9px;margin-bottom:18px}h1{font-size:30px;line-height:1.35;font-weight:700;margin:0 0 10px;color:#000}h2{font-size:22px;line-height:1.4;margin:0 0 14px;color:#000}h3{font-size:16px;line-height:1.4;margin:18px 0 7px;color:#000}p{margin:8px 0 12px}a{color:#265c46;text-decoration:underline;overflow-wrap:anywhere}.subtitle{font-size:13px;color:#555}.lead{font-size:16px}.figure{margin:16px 0 12px}.figure img{display:block;width:auto;max-width:100%;height:auto;max-height:350px;margin:0 auto;object-fit:contain;object-position:center;border:1px solid #d9d9d9}.caption{font-size:12px;color:#555;margin-top:5px;text-align:center}.foot{position:absolute;bottom:21px;left:56px;right:56px;display:flex;justify-content:space-between;font-size:11px;color:#555;border-top:1px solid #d9d9d9;padding-top:8px}table{width:100%;border-collapse:collapse;table-layout:auto;margin:12px 0 17px;font-size:13px;line-height:1.55}td,th{border:1px solid #d9d9d9;padding:8px 10px;vertical-align:middle;overflow-wrap:anywhere}th{background:#e6edf2;text-align:left;color:#000}tbody tr:nth-child(even){background:#f7f8f8}.small{font-size:13px}.flow{display:flex;align-items:center;justify-content:space-between;gap:8px;margin:20px 0}.flow span{border:1px solid #aaa;padding:13px 8px;text-align:center;flex:1;font-size:13px}.arrow{font-size:18px;color:#444}.architecture{display:grid;grid-template-columns:1fr 34px 1fr 34px 1fr;align-items:center;margin:20px 0}.architecture div{border:1px solid #aaa;text-align:center;padding:22px 10px;font-size:13px}.architecture i{text-align:center;font-style:normal;font-size:22px}ul,ol{padding-left:24px;margin:8px 0 14px}li{margin:5px 0}.twocol{display:grid;grid-template-columns:1fr 1fr;gap:22px}.source{font-size:12px;color:#555}.mono{font-family:Consolas,"Microsoft YaHei",monospace;font-size:13px;overflow-wrap:anywhere}.compact td,.compact th{padding:6px 9px}@media print{body{background:white}.page{margin:0;box-shadow:none}}'''
def fig(n,cap,height=350):return f'<figure class="figure"><img style="max-height:{height}px" src="assets/{n}.png"><figcaption class="caption">{cap}</figcaption></figure>'
def table(headers,rows,cls=''):
    return '<table class="'+cls+'"><thead><tr>'+''.join('<th>'+str(x)+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(x)+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table>'
def write(name,title,pages):
    body=''.join(f'<section class="page"><div class="running">青禾集校园二手交易平台　|　线下交易版　|　2026年11月6日</div>{content}<div class="foot"><span>{title}</span><span>{i+1} / {len(pages)}</span></div></section>' for i,content in enumerate(pages))
    (O/(name+'.html')).write_text('<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><title>'+title+'</title><style>'+css+'</style></head><body>'+body+'</body></html>',encoding='utf-8')
manual=[]
manual.append('''<h1>青禾集产品功能图文说明书</h1><p class="subtitle">校园二手交易平台　线下交易版</p><p class="lead">青禾集面向明故宫、将军路和天目湖三个校区，帮助同学发布闲置、发现商品、站内私信约定面交地点，并保留商品状态历史。</p><p><b>网站</b>　<a href="https://campus-market-v2-six.vercel.app">https://campus-market-v2-six.vercel.app</a><br><b>后台</b>　<a href="https://campus-market-v2-six.vercel.app/admin/">https://campus-market-v2-six.vercel.app/admin/</a></p>'''+fig('01-home','图 1 正式网站首页　截图中的商品为演示数据',320)+'''<h3>一次完整使用流程</h3><p>注册登录 → 搜索商品 → 查看卖家校区 → 私信商定时间地点 → 线下验货并自行付款 → 卖家标记已售出。</p><p>平台提供信息发布与沟通，不提供钱包、充值、付款、托管、退款、提现或结算。网站直接通过浏览器访问，不需要访问者启动终端。</p><p class="small">版本说明：本文全部截图采集自新版正式网站，仅使用演示账号和示例联系信息。旧版模拟订单仅作为双方可见的只读历史保留。</p>''')
manual.append('''<h2>搜索商品与设置个人资料</h2><p>在首页商品区输入标题或描述关键词。点击搜索旁的筛选图标，按需展开条件；不用筛选时首页保持简洁。</p>'''+fig('02-filters-focus','图 2 点击图标展开筛选　支持三校区选择',340)+'''<h3>筛选与排序</h3><p>可选商品类别、卖家所在校区、最低和最高价格、发布起止日期，以及时间或价格升降序。提交后显示已用条件，翻页保留条件。无匹配商品时可清除条件重新搜索。</p><h3>注册登录与账号设置</h3><p>未登录时可浏览公开商品；发布、收藏和私信需要登录。登录页可进入注册页，账号设置中可修改密码、个人简介、默认联系方式与所在校区。</p><p>明故宫、将军路和天目湖是卖家所属校区；实际见面地点应在私信中另行确认。个人主页默认不公开，用户可自行开启。</p><h3>联系方式的公开范围</h3><p>默认联系方式保存在账号资料中不会自动公开。发布商品时可预填并修改；商品通过审核且在售时，商品上的联系方式会向访问者公开。修改默认联系方式不会覆盖旧商品。</p><p class="small">公开体验账号：demo_student / CampusDemo2026!。这是共享账号，请勿填写真实隐私；建议注册自己的账号。</p>''')
manual.append('''<h2>发布商品与使用智能分类</h2><p>点击“发布闲置”，填写标题、描述、价格、类别及联系信息，可选上传商品图片。</p>'''+fig('05-classification-focus','图 3 标题与描述调用实际训练模型　建议类别由用户确认',520)+'''<ol><li>先写清商品名称、用途、成色和配件，再点击“智能分类”。</li><li>模型返回建议类别；点击采用建议，或手动选择其他类别。</li><li>检查联系信息的公开提示，确认后提交，商品进入待审核状态。</li></ol><p>当前模型为中文字符级 TF-IDF 与 MultinomialNB，网页调用已训练模型，不在请求中重新训练，也不调用大模型 API。页面不展示保证正确的概率。</p><p class="small">图片支持 JPEG、PNG、WebP，最大 3 MB、2000 万像素。输入为空、模型缺失或图片不合规会给出明确提示，用户仍可手动选择类别。</p>''')
manual.append('''<h2>商品审核与修改管理</h2><p>普通用户提交和修改商品后，需经管理员审核。卖家可在“我的发布”和商品详情查看待审核、通过或驳回状态。</p>'''+fig('07-review-focus','图 4 管理员审核表单　选择审核结果并保存',340)+table(['角色','操作与结果'],[['管理员','进入后台商品列表，点击“审核”或商品标题进入；通过后公开展示。'],['管理员','驳回时必须填写理由；理由会显示给卖家。'],['卖家','按驳回理由修改标题、描述、价格、图片或联系方式后重新提交审核。'],['其他用户','不能编辑、下架或修改别人的商品状态。']])+'''<p>后台使用独立管理员账号，普通注册不会获得后台权限。管理员密码不写入说明书或公开仓库。</p><p>卖家修改商品后会重新审核，审核前不会继续出现在公开商品市场。历史模拟订单不会再阻止当前商品的编辑或状态管理。</p><p class="small">审核只确认是否允许上架，不代表平台对商品质量、真伪或线下付款作担保。</p>''')
manual.append('''<h2>私信协商与线下面交</h2><p>商品详情显示卖家校区。登录后点击“私聊卖家 / 协商交易地点”，即可进入与该商品关联的双方会话。</p>'''+fig('10-chat-focus','图 5 双方私信与地点建议　消息仅双方可访问',370)+'''<h3>发送地点建议</h3><p>在会话下方选择校区、填写具体地点，例如“将军路校区南区操场北入口”，点击“发送地点建议”。买卖双方都可使用，建议会保存为一条私信，不会创建订单或冻结商品。</p><h3>确认时间并线下交易</h3><p>双方继续通过私信确认见面时间、地点、商品情况和价格。到场验货后，付款方式由双方自行协商，平台不接收或保管款项。</p><p>私信采用留言方式，点击“刷新消息”查看新留言。退出、刷新或更换浏览器登录后，仍可从“我的私信”找到原会话。</p><p class="small">只有会话双方能通过网页访问消息。地点建议并不代表对方已同意，应等待对方回复确认。建议在校内公共场所面交。</p>''')
manual.append('''<h2>个人中心与商品历史</h2><p>交易完成后，卖家进入“个人中心”，在对应商品的“调整交易状态”中选择“已售出”并更新。仅商品所有者能执行这项操作。</p>'''+fig('15-status-focus','图 6 卖家管理在售　已售出　已下架状态',340)+'''<h3>商品状态与历史记录</h3><p>已售出或已下架商品不再出现在首页在售市场中，个人中心保留商品及状态变更历史。公开主页允许他人查看审核通过商品及其状态；关闭主页后，他人不能浏览个人中心。</p><p>重新上架需要再次审核。下架保留历史，不会将商品和双方私信直接删除。标记已售出是卖家更新展示状态，不代表平台验证过付款或交付。</p><h3>收藏与违规举报</h3><p>商品详情可收藏或取消收藏，并在“我的收藏”统一查看。发现违规商品可从他人商品详情提交举报，在“我的举报”查看处理进度和管理员记录的结果。</p><h3>旧版记录与常见情况</h3><p>有旧模拟订单的用户可在“我的私信”下方进入“历史模拟记录”，仅可查看，不能继续付款、退款或结算。没有商品、没有私信、未设置校区或模型不可用时，页面会提示下一步操作。</p>''')
write('01 产品功能图文说明书','产品功能图文说明书',manual)
design=[]
design.append('''<h1>产品设计思路与机器学习实现</h1><p class="subtitle">青禾集校园二手交易平台　线下交易版</p><p class="lead">本项目以校园闲置物品流转为场景，将商品发现、发布审核、校区识别和私信沟通串成完整路径。智能分类帮助发布者选择类别，最终类别仍由用户决定。</p><h3>从实际场景确定基础功能</h3><p>小组先围绕教材、数码配件、运动器材和宿舍用品讨论需求，确定买家、卖家和管理员三类角色。基础功能包括注册登录、搜索筛选、商品详情、发布管理和收藏，再通过验收逐步补充管理后台、审核、个人中心、三校区信息与举报。</p><h3>当前产品边界</h3><p>最终采用“线上沟通，线下自行交易”。平台保留私信、地点建议与售出历史，移除钱包、模拟付款、托管和结算。收缩范围后，演示和实际使用都可围绕信息与沟通展开，避免将资金管理能力当作已经具备的服务。</p><div class="flow"><span>发布审核</span><b class="arrow">→</b><span>发现商品</span><b class="arrow">→</b><span>私信约地点</span><b class="arrow">→</b><span>线下交易</span><b class="arrow">→</b><span>标记已售出</span></div><h3>整体架构</h3><div class="architecture"><div>电脑与手机浏览器<br>页面交互与表单</div><i>↔</i><div>Vercel 上的 Django<br>认证 权限 审核 私信<br>scikit learn 分类模型</div><i>↔</i><div>Neon PostgreSQL<br>账号 商品 图片<br>收藏 私信 状态历史</div></div><p>前端模板和后端部署在同一站点，图片与业务数据保存到持久化数据库。访问者打开网址即可操作，不依赖开发者本机服务。</p><p class="small">正式入口：<a href="https://campus-market-v2-six.vercel.app">https://campus-market-v2-six.vercel.app</a><br>代码仓库：<a href="https://github.com/observer-97/campus-market-v2">github.com/observer-97/campus-market-v2</a></p>''')
design.append('''<h2>从详细提示词到持续验收</h2><p>开发采用先定义范围、再生成实现、再用实际操作验收的方式。AI 负责辅助编写代码与材料，小组通过具体场景判断功能是否可用，并据此提出下一轮修改。</p>'''+table(['阶段','发现的问题','迭代后的处理'],[['基础版本','只列出页面不足以完成交易信息流转','实现认证、发布、搜索、详情、收藏和个人发布管理。'],['图形化后台','数据管理依赖命令，审核入口不直观','加入 Django 管理后台，商品列表增加明确的“审核”按钮。'],['审核与归属','商品修改后内容可能改变，不能只靠前端限制','编辑和状态操作校验所有者；修改后重新审核，驳回保留理由。'],['校园与沟通','三个校区距离不同，单有联系方式不够','展示卖家校区，支持按校区筛选、双方私信及具体地点建议。'],['首页与账号','筛选项过多，联系方式公开范围不清','突出关键词搜索，筛选改为图标展开；账号设置增加公开提示。'],['交易方式收敛','模拟托管不能等同真实资金服务','移除支付操作，保留线下沟通和只读旧记录。']])+'''<h3>提示词设计示例</h3><p class="small">以下为依据开发需求整理的提示词摘要，不是逐字聊天导出。</p><p>使用 Django 自带认证实现校园二手平台。商品支持关键词与分类筛选、发布、编辑、收藏；只有所有者可以修改和下架。采用中文字符级 TF-IDF，比较朴素贝叶斯与逻辑回归，保留真实训练评估产物。发布页面调用已训练模型，分类建议由用户确认。先检查现有素材，数据不足时明确示例来源，不编造效果。</p><h3>验收驱动修改</h3><p>每次新增需求同时检查正常流程、空状态和越权操作。例如增加审核后测试未审核商品是否被他人看见；移除支付后，不仅隐藏按钮，还直接调用旧接口验证其无法继续修改数据。</p>''')
design.append('''<h2>智能分类的数据与训练方式</h2><p>机器学习任务是将标题和描述拼接后的中文文本，预测为学习用品、电子用品、体育用品或生活用品。它减少发布时的分类选择成本，不负责估价、鉴定或判断交易安全。</p><h3>数据来源与格式</h3><p>现有评估使用 97 条 AI 辅助逐条编写的中文标注示例：学习用品 25 条，其他三类各 24 条。它们不是真实用户交易数据，也不是从二手网站爬取的数据。</p><p class="mono">CSV 字段：id、title、description、category、source、group_id</p><p>source 记录来源，group_id 标记同物品或同模板表达家族。后续可按相同格式补充经授权、去隐私且人工复核标签的真实样本。</p><h3>清洗与防止泄漏</h3><p>训练命令校验必需字段与类别，清理缺失及标准化后重复数据；本次清洗后仍为 97 条。划分前合并人工同组样本，以及字符二元组 Jaccard ≥ 0.65 或序列相似度 ≥ 0.82 的近重复对；得到 96 个组。启发式分组可能漏检，仍需人工检查。</p>'''+table(['用途','样本数','用途限制'],[['训练集','58','仅在此拟合 TF-IDF 词表、权重与分类器。'],['验证集','21','按 Macro-F1，再按 Accuracy 选择模型；同分优先 NB。'],['最终测试集','18','选型后评估一次，不据此反向挑选部署算法。']])+'''<h3>特征与算法</h3><p>固定随机种子 20261022，使用分组分层工具构造一次留出划分。字符级 TF-IDF 使用 1–3 gram、min_df=1、sublinear_tf=True，不依赖中文分词。比较 MultinomialNB（alpha=0.5）和 LogisticRegression（C=4、max_iter=1500）。</p><p>独立命令 <span class="mono">python manage.py train_model</span> 输出模型、划分清单和评估文件。网页只加载并校验本项目模型，调用预测；不在请求中训练，也不以关键词规则或大模型 API 替代训练。</p>''')
rows=[]
for name,r in E['results'].items(): rows.append([name,f"{r['validation']['accuracy']:.4f}",f"{r['validation']['macro_f1']:.4f}",f"{r['test']['accuracy']:.4f}",f"{r['test']['macro_f1']:.4f}"])
pc=E['results']['MultinomialNB']['test']['per_class'];labels=E['metadata']['labels'];cm=E['results']['MultinomialNB']['test']['confusion_matrix']
design.append('''<h2>模型评估结果与错误分析</h2><p>以下数字读取自项目实际保存的 artifacts/evaluation.json。本轮修改没有重新训练模型，也没有将浏览器演示成功当作分类准确率。</p>'''+table(['算法','验证 Accuracy','验证 Macro F1','测试 Accuracy','测试 Macro F1'],rows,'compact')+'''<p>两算法在当前划分上同分，因此按预设规则部署 MultinomialNB；这不能说明 NB 在其他数据上一定更好。测试正确 14/18 条。</p><h3>部署模型各类测试指标</h3>'''+table(['类别','Precision','Recall','F1','样本数'],[[labels[k],f"{pc[k]['precision']:.4f}",f"{pc[k]['recall']:.4f}",f"{pc[k]['f1-score']:.4f}",int(pc[k]['support'])] for k in E['class_order']],'compact')+'''<h3>测试混淆矩阵</h3>'''+table(['真实类别 ↓ 预测 →','学习','电子','体育','生活'],[[labels[k]]+row for k,row in zip(E['class_order'],cm)],'compact')+'''<p class="small">两算法本次矩阵相同。Accuracy 是整体正确比例；Macro-F1 对每类 F1 等权平均，可暴露弱类别。生活用品的 Recall 只有 0.20，不能用总体准确率掩盖。</p><h3>代表性错误与局限</h3><p>折叠雨伞、帆布托特包被分为体育；桌面化妆镜被分为电子；冬季棉被被分为学习。97 条编写示例和 18 条测试样本不足以代表真实表达分布。下一步应增加真实且授权的数据、加强生活用品表达与近重复审核，再建立新的固定测试集。</p>''')
design.append('''<h2>后端约束与实际验证</h2><p>权限由后端检查，按钮只是操作入口。用户不能修改他人商品或读取他人私信，未审核商品及图片限制访问；图片同时校验格式、大小与像素范围。</p><h3>移除支付时的兼容处理</h3><p>旧数据库表保留，避免丢失已有记录。原领取余额、发起模拟订单及订单动作接口停用，登录用户调用返回 410；越权访问他人记录返回 404。旧模拟订单只读，不再锁定商品；当前浏览私信不会创建钱包。</p><p>见面地点建议保存为双方私信，交易完成由卖家更新商品展示状态。平台不验证真实付款，不生成收据或资金结算结果。</p><h3>本次执行的验证</h3>'''+table(['检查','实际结果与范围'],[['本地自动化','53 项通过，42.478 秒；包括旧接口停用、历史隐私、地点校验、CSRF、所有权与商品状态历史。'],['跨进程持久化','隔离数据库的写入、读取两进程通过；账号会话、图片哈希、收藏、私信地点及已售状态保留。'],['GitHub CI','新版代码的 Linux 与 PostgreSQL 回归、跨进程检查及匿名公网访问检查通过。'],['真实网站','24 项浏览器检查通过；涵盖分类、发布审核、收藏、地点私信、已售历史和旧支付入口失效。'],['移动端','390×844 浏览器视口首页和私信无横向溢出，独立会话能读取消息；未实测实体手机。']])+'''<h3>部署与证据</h3><p>Vercel 运行前端模板、Django 接口和模型；Neon PostgreSQL 持久化业务数据与图片。生产初始化可重复执行，不覆盖已有密码、商品和审核状态。管理员密码仅通过私密配置保存。</p><p class="source">证据：market/test_trading.py、tools/check_persistence.py、docs/offline-v3-browser-verification.json、GitHub Actions，以及新版真实截图。历史版本的支付测试仅说明当时功能，不能作为本版功能说明。</p>''')
design.append('''<h2>七分钟展示安排与小组分工</h2><p>演示围绕一件商品展开，提前准备一个卖家账号、一个买家账号和独立管理员会话。以下为建议时长，尚未进行真人计时排练。</p>'''+table(['时间','展示内容'],[['0:00–0:40','说明三校区闲置交易场景与线上沟通、线下交易的边界。'],['0:40–1:30','展示首页关键词、校区筛选、详情与卖家校区。'],['1:30–2:40','卖家填写商品，点击真实智能分类，确认类别并发布。'],['2:40–3:30','管理员点击“审核”通过，买家看到商品并收藏。'],['3:30–4:30','买家私信并发送具体地点，卖家回复；线下交易后标记已售出。'],['4:30–5:40','说明详细提示词、后台与审核等迭代，以及为何最终移除支付。'],['5:40–7:00','介绍数据来源、TF-IDF、两算法对比、实际指标和小样本局限。']])+'''<h3>小组成员与分工</h3>'''+table(['姓名','实际承担工作','工作量占比'],[['待填写','需求讨论与产品设计　按实际情况填写','待填写'],['待填写','开发验收与部署　按实际情况填写','待填写'],['待填写','数据评估与展示材料　按实际情况填写','待填写']])+'''<p class="small">提交前按真实参与情况调整成员行数、分工与比例，合计应为 100%。此处不预填虚构成员。</p><h3>AI 使用说明与后续改进</h3><p>使用 Codex 辅助代码实现、回归检查、部署与材料整理；上述对话思路为需求摘要。Token 消耗及费用待依据账户用量记录和账单核实填写，本文不将估算当作账单。</p><p>优先改进真实标注数据、私信通知体验和可访问性。当前不提供真实支付、物流、实名认证或个性化推荐，不承诺模型效果或所有地区的网络可用性。</p>''')
